//! 🧮️ Authored TIFF storage cells are admitted before complete logical Snapshot construction.
 use super::{TiffSnapshot,ValueError,ValueRefusalKind,SqliteSnapshotControl,SqliteSnapshotPhase,RowWriter};
 use semio_framework_value::{DslValue as D,NativeDecodeControl};
 use semio_framework_dsl_record::{RecordValue,FieldValue as F};
 use semio_framework_os_kernel::{ArtifactSqliteSnapshot as _,sqlite_snapshot::SqliteDatabaseLimits};
 type Result<T>=std::result::Result<T,ValueError>;
 const TABLES:[(&str,usize);17]=[("tiff_ascii_value",4),("tiff_byte_value",4),("tiff_block",8),("tiff_sample",5),("tiff_document",2),("tiff_double_value",5),("tiff_float_value",6),("tiff_ifd",3),("tiff_long_value",4),("tiff_rational_value",5),("tiff_short_value",4),("tiff_signed_byte_value",4),("tiff_signed_long_value",4),("tiff_signed_rational_value",5),("tiff_signed_short_value",4),("tiff_tag",5),("tiff_undefined_value",4)];
 fn invalid()->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,"TIFF native value differs from authored role")}
 fn add(left:usize,right:usize)->Result<usize>{left.checked_add(right).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"TIFF semantic bytes overflow"))}
 pub(super) fn extent(limits:SqliteDatabaseLimits)->Result<()>{let mut bytes=0usize;for statement in TiffSnapshot::SQLITE_SCHEMA.split(';'){bytes=add(bytes,statement.trim().len())?;}for(name,_)in TABLES{bytes=add(bytes,name.len())?;}if bytes.max(TiffSnapshot::SQLITE_SCHEMA.len())>limits.max_schema_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"TIFF authored schema exceeds caller bytes"))}if limits.max_tables<TABLES.len()||TABLES.iter().any(|(_,width)|*width>limits.max_columns)||limits.max_rows<1{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"TIFF authored relational extent exceeds caller limits"))}Ok(())}
 pub(super) fn typed(snapshot:&TiffSnapshot,phase:SqliteSnapshotPhase,control:&mut SqliteSnapshotControl<'_>)->Result<()>{extent(control.limits())?;let mut writer=RowWriter::borrowed(control,phase)?;super::visit_rows(snapshot,&mut writer)?;writer.finish_borrowed()}
 fn array(value:&D)->Result<&[D]>{value.as_array().ok_or_else(invalid)}
 fn object(value:&D)->Result<&[(String,D)]>{value.as_object().ok_or_else(invalid)}
 fn field<'a>(entries:&'a[(String,D)],key:&str,native:&mut NativeDecodeControl<'_>)->Result<Option<&'a D>>{native.scoped_stage(|native|{native.begin_stage(entries.len())?;let mut found=None;for(name,value)in entries{if name==key{found=Some(value)}native.step()?;}Ok(found)})}
 fn required<'a>(entries:&'a[(String,D)],key:&str,native:&mut NativeDecodeControl<'_>)->Result<&'a D>{field(entries,key,native)?.ok_or_else(invalid)}
 fn text<'a>(value:&'a D,native:&mut NativeDecodeControl<'_>)->Result<&'a str>{let value=value.as_str().ok_or_else(invalid)?;native.borrow_text(value.as_bytes())?;Ok(value)}
 fn unsigned(value:&D,maximum:u64)->Result<u64>{value.as_u64().filter(|value|*value<=maximum).ok_or_else(invalid)}
 fn signed(value:&D,minimum:i64,maximum:i64)->Result<i64>{value.as_i64().filter(|value|*value>=minimum&&*value<=maximum).ok_or_else(invalid)}
 fn class(value:f64)->&'static str{if value.is_nan(){"nan"}else if value==f64::INFINITY{"positiveInfinity"}else if value==f64::NEG_INFINITY{"negativeInfinity"}else{"finite"}}
 struct Census<'c,'p>{native:&'c mut NativeDecodeControl<'p>,limits:SqliteDatabaseLimits,rows:usize,bytes:usize}
 impl Census<'_,'_>{fn row(&mut self,payload:usize)->Result<()>{let rows=self.rows.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"TIFF semantic rows overflow"))?;let bytes=add(self.bytes,payload)?;if rows>self.limits.max_rows{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"TIFF semantic rows exceed caller limit"))}if bytes>self.limits.max_value_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"TIFF semantic values exceed caller limit"))}self.native.step()?;self.rows=rows;self.bytes=bytes;Ok(())}
 fn values(&mut self,value:&D)->Result<()>{let entries=object(value)?;let kind=text(required(entries,"kind",self.native)?,self.native)?;let values=array(required(entries,"value",self.native)?)?;for value in values{let bytes=match kind{"byte"|"undefined"=>{unsigned(value,u64::from(u8::MAX))?;32},"ascii"=>{let value=text(value,self.native)?;if !value.is_ascii()||value.contains('\0'){return Err(invalid())}24+value.len()},"short"=>{unsigned(value,u64::from(u16::MAX))?;32},"long"=>{unsigned(value,u64::from(u32::MAX))?;32},"sByte"=>{signed(value,i64::from(i8::MIN),i64::from(i8::MAX))?;32},"sShort"=>{signed(value,i64::from(i16::MIN),i64::from(i16::MAX))?;32},"sLong"=>{signed(value,i64::from(i32::MIN),i64::from(i32::MAX))?;32},"rational"|"sRational"=>{let pair=array(value)?;if pair.len()!=2{return Err(invalid())}for value in pair{if kind=="rational"{unsigned(value,u64::from(u32::MAX))?;}else{signed(value,i64::from(i32::MIN),i64::from(i32::MAX))?;}self.native.step()?;}40},"float"=>{let entries=object(value)?;unsigned(required(entries,"bits",self.native)?,u64::from(u32::MAX))?;64},"double"=>{let entries=object(value)?;unsigned(required(entries,"lo",self.native)?,u64::from(u32::MAX))?;unsigned(required(entries,"hi",self.native)?,u64::from(u32::MAX))?;40},_=>return Err(invalid())};self.row(bytes)?;}if !["byte","ascii","short","long","rational","sByte","undefined","sShort","sLong","sRational","float","double"].contains(&kind){return Err(invalid())}Ok(())}
 fn ifd(&mut self,value:&D)->Result<()>{let entries=object(value)?;self.row(24)?;for block in array(required(entries,"blocks",self.native)?)?{let block=object(block)?;for key in ["x","y","width","height","channels"]{unsigned(required(block,key,self.native)?,u64::from(u32::MAX))?;}self.row(64)?;for sample in array(required(block,"samples",self.native)?)?{let sample=object(sample)?;unsigned(required(sample,"lo",self.native)?,u64::from(u32::MAX))?;unsigned(required(sample,"hi",self.native)?,u64::from(u32::MAX))?;self.row(40)?;}}for entry in array(required(entries,"entries",self.native)?)?{let entry=object(entry)?;unsigned(required(entry,"tag",self.native)?,u64::from(u16::MAX))?;self.row(40)?;let values=required(entry,"values",self.native)?;self.values(values)?;}Ok(())}}
 pub(super) fn borrowed(record:&RecordValue,limits:SqliteDatabaseLimits,native:&mut NativeDecodeControl<'_>)->Result<()>{extent(limits)?;native.scoped_stage(|native|{native.begin_stage(0)?;if record.fields.len()!=2||record.fields.keys().any(|id|!(1..=2).contains(id)){return Err(invalid())}let schema=match record.get(1){Some(F::Text(schema))=>{native.borrow_text(schema.as_bytes())?;schema},_=>return Err(invalid())};let ifds=match record.get(2){Some(F::Value(value))=>array(value)?,_=>return Err(invalid())};let mut census=Census{native,limits,rows:0,bytes:0};census.row(add(8,schema.len())?)?;for ifd in ifds{census.ifd(ifd)?;}census.native.checkpoint()})}
 